package com.acme.calendar.booking;

import java.time.Instant;

/**
 * Blocks booking an appointment that overlaps an existing one for the same attendee.
 */
public class OverlapGuard {

    private final AppointmentRepository appointments;

    public OverlapGuard(AppointmentRepository appointments) {
        this.appointments = appointments;
    }

    public void assertNoOverlap(String attendeeId, Instant start, Instant end) {
        if (appointments.existsOverlapping(attendeeId, start, end)) {
            throw new OverlapException(attendeeId, start, end);
        }
    }
}

class OverlapException extends RuntimeException {
    public OverlapException(String attendee, Instant start, Instant end) {
        super("Attendee " + attendee + " already has an appointment overlapping " + start + " - " + end);
    }
}

