package com.acme.calendar.availability;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

/**
 * Computes free slots for an attendee between two instants.
 */
public class FreeSlotCalculator {

    private final AppointmentRepository appointments;
    private final WorkingHoursPolicy hours;

    public FreeSlotCalculator(AppointmentRepository appointments, WorkingHoursPolicy hours) {
        this.appointments = appointments;
        this.hours = hours;
    }

    public List<Slot> freeSlots(String attendeeId, Instant from, Instant to, Duration duration) {
        List<Slot> result = new ArrayList<>();
        for (Slot working : hours.windowsFor(attendeeId, from, to)) {
            for (Slot candidate : splitByExisting(working, appointments.findByAttendee(attendeeId, working.getStart(), working.getEnd()))) {
                if (!candidate.getDuration().minus(duration).isNegative()) {
                    result.add(candidate);
                }
            }
        }
        return result;
    }

    private List<Slot> splitByExisting(Slot working, List<Appointment> existing) {
        List<Slot> parts = new ArrayList<>();
        Instant cursor = working.getStart();
        existing.sort(java.util.Comparator.comparing(Appointment::getStart));
        for (Appointment a : existing) {
            if (a.getStart().isAfter(cursor)) parts.add(new Slot(cursor, a.getStart()));
            if (a.getEnd().isAfter(cursor)) cursor = a.getEnd();
        }
        if (cursor.isBefore(working.getEnd())) parts.add(new Slot(cursor, working.getEnd()));
        return parts;
    }
}

