import org.springframework.web.bind.annotation.RestController;

/**
 * Appointment creation endpoint: check overlaps, persist, notify invitees.
 */
@RestController
public class CreateAppointmentController {

    private final OverlapGuard overlapGuard;
    private final AppointmentRepository appointments;
    private final InvitationSender invitations;

    public CreateAppointmentController(OverlapGuard overlapGuard, AppointmentRepository appointments, InvitationSender invitations) {
        this.overlapGuard = overlapGuard;
        this.appointments = appointments;
        this.invitations = invitations;
    }

    @PostMapping("/appointments")
    public AppointmentView create(@RequestBody CreateAppointmentRequest req) {
        for (String attendee : req.getAttendeeIds()) {
            overlapGuard.assertNoOverlap(attendee, req.getStart(), req.getEnd());
        }
        Appointment appt = appointments.save(Appointment.of(req));
        for (String attendee : req.getAttendeeIds()) {
            invitations.send(attendee, appt);
        }
        return AppointmentView.from(appt);
    }
}

