import java.util.List;

/**
 * Sends reminders for appointments starting in approximately one hour.
 */
public class ReminderScheduler {

    private static final Duration LEAD_TIME = Duration.ofHours(1);

    private final AppointmentRepository appointments;
    private final NotificationGateway notifier;

    public ReminderScheduler(AppointmentRepository appointments, NotificationGateway notifier) {
        this.appointments = appointments;
        this.notifier = notifier;
    }

    public void runAt(Instant now) {
        Instant target = now.plus(LEAD_TIME);
        List<Appointment> due = appointments.findStartingBetween(target.minus(Duration.ofMinutes(5)), target.plus(Duration.ofMinutes(5)));
        for (Appointment a : due) {
            for (String attendee : a.getAttendeeIds()) {
                notifier.send(attendee, "Your appointment starts in one hour");
            }
        }
    }
}

