package com.acme.calendar.recurrence;

import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;

/**
 * Expands a weekly recurrence into concrete appointment occurrences.
 */
public class WeeklyRecurrenceExpander {

    private final int maxOccurrences;

    public WeeklyRecurrenceExpander(int maxOccurrences) {
        this.maxOccurrences = maxOccurrences;
    }

    public List<Appointment> expand(RecurringDefinition def) {
        if (def.getIntervalWeeks() <= 0) {
            throw new IllegalArgumentException("Interval must be positive");
        }
        List<Appointment> results = new ArrayList<>();
        Instant cursor = def.getStart();
        int count = 0;
        while (count < maxOccurrences && !cursor.isAfter(def.getUntil())) {
            results.add(Appointment.ofRecurring(def, cursor));
            cursor = cursor.plus(def.getIntervalWeeks() * 7L, ChronoUnit.DAYS);
            count++;
        }
        return results;
    }
}

