import javax.persistence.EntityTransaction;

/**
 * Persists an audit entry on each appointment change.
 */
public class AppointmentChangeAuditor {

    private final EntityManager em;

    public AppointmentChangeAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String appointmentId, String changeType, String previousJson, String newJson, String actorId) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            AppointmentAuditEntry e = new AppointmentAuditEntry();
            e.setAppointmentId(appointmentId);
            e.setChangeType(changeType);
            e.setPreviousJson(previousJson);
            e.setNewJson(newJson);
            e.setActorId(actorId);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

