/* calendar_export.c - write iCalendar file for a user's appointments */
#include <stdio.h>
#include "calendar_db.h"

int export_ical(const char *user_id, const char *from, const char *to, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Acme//Calendar//EN\r\n");

    db_cursor_t *cur = NULL;
    if (db_open_appointments_cursor(&cur, user_id, from, to) != DB_OK) { fclose(out); return -2; }

    int events = 0;
    appointment_row_t row;
    while (db_appointment_cursor_next(cur, &row) == DB_OK) {
        if (row.status == APPT_CANCELLED) continue;
        fprintf(out, "BEGIN:VEVENT\r\nUID:%s\r\nDTSTART:%s\r\nDTEND:%s\r\nSUMMARY:%s\r\nEND:VEVENT\r\n",
                row.appointment_id, row.starts_at, row.ends_at, row.title);
        events++;
    }
    db_close_cursor(cur);
    fprintf(out, "END:VCALENDAR\r\n");
    fclose(out);
    return events;
}

